/**  One relevant `docker events` entry. */
export type DockerEvent = {
	/**  `container`, `image`, `volume`, `network`. */
	object: string,
	action: string,
	id: string,
	name: string | null,
};

export type DockerImage = {
	id: string,
	/**  `<none>` for dangling images. */
	repository: string,
	tag: string,
	size: string,
	createdSince: string,
};

/**  A line of `docker logs` output. */
export type DockerLogLine = {
	stderr: boolean,
	text: string,
};

export type DockerNetwork = {
	id: string,
	name: string,
	driver: string,
	scope: string,
	composeProject: string | null,
};

export type DockerObject = "container" | "image" | "volume" | "network";

/**  A registry to log in to (Docker Hub, GHCR, a private one). The password is stored separately. */
export type DockerRegistry = {
	id: string,
	name: string,
	/**  `docker.io`, `ghcr.io`, `registry.example.com:5000`. */
	address: string,
	username?: string,
};

export type DockerSettings = {
	connections?: DockerConnection[],
	registries?: DockerRegistry[],
};

/**  Everything the Services tree shows, fetched in one go. */
export type DockerSnapshot = {
	availability: DockerAvailability,
	/**  The docker executable in use, e.g. for `docker exec -it` in a terminal. */
	executable: string | null,
	containers: DockerContainer[],
	images: DockerImage[],
	volumes: DockerVolume[],
	networks: DockerNetwork[],
	/**  Lists that failed although the daemon answered (shown, not fatal). */
	errors: string[],
	/**  Global CLI options selecting the connection's daemon (for `docker exec` in a terminal). */
	globalArgs?: string[],
};

export type DockerVolume = {
	name: string,
	driver: string,
	mountpoint: string,
	composeProject: string | null,
};

/**  What the UI needs to show an opened document. */
export type DocumentInfo = {
	id: DocId,
	path: IpcPath,
	text: string,
	version: number,
	language: LanguageId,
	encoding: string,
	lineEnding: LineEnding,
	readOnly: boolean,
	dirty: boolean,
	/**
	 *  Larger than `ide_vfs::LARGE_FILE_THRESHOLD`: language servers, syntax
	 *  structure and folding are disabled; the editor should drop heavy features.
	 */
	large?: boolean,
	/**  Effective `.editorconfig` properties, when any section applies. */
	editorconfig?: EditorConfigProps | null,
	/**
	 *  Set for read-only virtual documents (library classes a language server
	 *  provides, e.g. `jdt://…`); `path` then holds the same URI.
	 */
	uri?: string | null,
};

/**
 *  A link in a document (`textDocument/documentLink`): an HTML `href`, a
 *  Markdown link, an `#include`, a JSON `$schema`…
 */
export type DocumentLink = {
	range: Range,
	/**  A `file:` target. */
	path: IpcPath | null,
	/**  The `#fragment` of a `file:` target (`L12`, `L12,5`, a heading or element id). */
	fragment: string | null,
	/**  Any other target (`https:`, …). */
	url: string | null,
	tooltip: string | null,
};

export type DuplicateGroup = {
	tokens: number,
	/**  Lines of the first fragment. */
	lines: number,
	language: LanguageId,
	fragments: Fragment[],
};

export type DuplicateOptions = {
	/**  Shortest duplicate reported, in tokens. */
	minTokens: number,
	/**  Treat all identifiers as equal (finds copies with renamed variables). */
	anonymizeIdentifiers: boolean,
	/**  Treat all literals as equal. */
	anonymizeLiterals: boolean,
};

export type DuplicatesReport = {
	groups: DuplicateGroup[],
	/**  Files tokenised (files without a grammar are skipped). */
	files: number,
	tokens: number,
	/**  More groups were found than reported. */
	truncated: boolean,
	cancelled: boolean,
	elapsedMs: number,
};

/**  An item of a frontend-listed menu slot. */
export type DynamicItem = {
	action: string,
	arg: string | null,
	label: string,
};

/**  Editor › General › Appearance. */
export type EditorAppearanceSettings = {
	caretBlinking?: boolean,
	/**  Blink period in ms. */
	caretBlinkPeriod?: number,
	blockCaret?: boolean,
	lineNumbers?: boolean,
	methodSeparators?: boolean,
	/**  Sub-options of `editor.showWhitespace`. */
	whitespaceLeading?: boolean,
	whitespaceInner?: boolean,
	whitespaceTrailing?: boolean,
	indentGuides?: boolean,
	/**  Right margin and visual guides from Code Style. */
	hardWrapGuides?: boolean,
	intentionBulb?: boolean,
	/**  Distraction Free Mode: width of the centred text column, in characters. */
	distractionFreeWidth?: number,
};

/**
 *  Effective EditorConfig properties of one file. `None` = not specified
 *  (or `unset`), so the IDE setting applies.
 */
export type EditorConfigProps = {
	indentStyle: IndentStyle | null,
	/**  Columns per indentation level (`indent_size = tab` resolves to `tab_width`). */
	indentSize: number | null,
	tabWidth: number | null,
	endOfLine: LineEnding | null,
	/**  `utf-8`, `utf-8-bom`, `utf-16le`, `utf-16be` or `latin1`. */
	charset: string | null,
	trimTrailingWhitespace: boolean | null,
	insertFinalNewline: boolean | null,
	maxLineLength: number | null,
};

/**  Editor › General (mouse, scrolling, soft wraps, virtual space, saving). */
export type EditorGeneralSettings = {
	/**  Change font size with ⌘ + mouse wheel. */
	wheelZoom?: boolean,
	/**  Drag-and-drop of selected text inside the editor. */
	dragAndDrop?: boolean,
	/**  When the caret moves out of view: `minimize` scrolling | `center` the caret line. */
	caretScroll?: string,
	/**  Glob patterns (`;`-separated) of files soft-wrapped when `editor.softWrap` is on. */
	softWrapFiles?: string,
	/**  Wrapped parts keep the original line's indent. */
	softWrapIndent?: boolean,
	/**  Show virtual space at the file bottom. */
	scrollPastEnd?: boolean,
	/**  Remove trailing spaces on save from: `modified` lines | `all` lines. */
	stripTrailingScope?: string,
	/**  Keep trailing spaces on the caret line when stripping. */
	keepTrailingOnCaretLine?: boolean,
	removeTrailingBlankLines?: boolean,
	/**  Copy as rich text (HTML with syntax colours) by default. */
	richTextCopy?: boolean,
};

export type EditorSettings = EditorSettings_Serialize | EditorSettings_Deserialize;

export type EditorSettings_Deserialize = {
	fontFamily?: string,
	fontSize?: number | null,
	lineHeight?: number | null,
	tabSize?: number,
	insertSpaces?: boolean,
	softWrap?: boolean,
	showWhitespace?: boolean,
	inlayHints?: boolean,
	stickyScroll?: boolean,
	formatOnSave?: boolean,
	/**  Editor colour scheme id; `theme-default` follows the IDE theme. */
	colorScheme?: string,
	/**  Color Scheme edits: scheme id → attribute id → override. */
	colorOverrides?: { [key in string]: { [key in string]: TextAttributesOverride_Deserialize } },
	/**
	 *  Color Scheme › Language Defaults › Semantic highlighting: local variables and
	 *  parameters get a colour derived from their name (IDEA's rainbow identifiers).
	 */
	semanticHighlighting?: boolean,
	/**  Color Scheme › Language Defaults › Rainbow brackets: `()`, `[]`, `{}` coloured by depth. */
	rainbowBrackets?: boolean,
	ligatures?: boolean,
	/**  Fallback font for glyphs the main font lacks; empty = none. */
	fallbackFont?: string,
	/**  Typography Settings › Main font weight (CSS 100–900), as IDEA. */
	fontWeight?: number,
	/**  Typography Settings › Bold font weight: wherever the editor renders bold. */
	boldFontWeight?: number,
	general?: EditorGeneralSettings,
	appearance?: EditorAppearanceSettings,
	breadcrumbs?: BreadcrumbsSettings,
	completion?: CompletionSettings,
	autoImport?: AutoImportSettings,
	folding?: FoldingSettings,
	tabs?: EditorTabsSettings,
	smartKeys?: SmartKeysSettings,
	codeEditing?: CodeEditingSettings,
	inlay?: InlayHintsSettings,
	inlineCompletion?: InlineCompletionSettings,
	/**  Gutter icon groups turned off (`run`, `breakpoints`, `bookmarks`, `vcs`, `blame`). */
	gutterIconsDisabled?: string[],
	showGutterIcons?: boolean,
	codeStyle?: CodeStyleSettings_Deserialize,
	encodings?: EncodingSettings,
};

export type EditorSettings_Serialize = {
	fontFamily: string,
	fontSize: number | null,
	lineHeight: number | null,
	tabSize: number,
	insertSpaces: boolean,
	softWrap: boolean,
	showWhitespace: boolean,
	inlayHints: boolean,
	stickyScroll: boolean,
	formatOnSave: boolean,
	/**  Editor colour scheme id; `theme-default` follows the IDE theme. */
	colorScheme: string,
	/**  Color Scheme edits: scheme id → attribute id → override. */
	colorOverrides: { [key in string]: { [key in string]: TextAttributesOverride_Serialize } },
	/**
	 *  Color Scheme › Language Defaults › Semantic highlighting: local variables and
	 *  parameters get a colour derived from their name (IDEA's rainbow identifiers).
	 */
	semanticHighlighting: boolean,
	/**  Color Scheme › Language Defaults › Rainbow brackets: `()`, `[]`, `{}` coloured by depth. */
	rainbowBrackets: boolean,
	ligatures: boolean,
	/**  Fallback font for glyphs the main font lacks; empty = none. */
	fallbackFont: string,
	/**  Typography Settings › Main font weight (CSS 100–900), as IDEA. */
	fontWeight: number,
	/**  Typography Settings › Bold font weight: wherever the editor renders bold. */
	boldFontWeight: number,
	general: EditorGeneralSettings,
	appearance: EditorAppearanceSettings,
	breadcrumbs: BreadcrumbsSettings,
	completion: CompletionSettings,
	autoImport: AutoImportSettings,
	folding: FoldingSettings,
	tabs: EditorTabsSettings,
	smartKeys: SmartKeysSettings,
	codeEditing: CodeEditingSettings,
	inlay: InlayHintsSettings,
	inlineCompletion: InlineCompletionSettings,
	/**  Gutter icon groups turned off (`run`, `breakpoints`, `bookmarks`, `vcs`, `blame`). */
	gutterIconsDisabled: string[],
	showGutterIcons: boolean,
	codeStyle: CodeStyleSettings_Serialize,
	encodings: EncodingSettings,
};

/**  Editor › General › Editor Tabs. */
export type EditorTabsSettings = {
	/**  `top` | `bottom` | `none`. */
	placement?: string,
	multipleRows?: boolean,
	/**  One row that doesn't fit: `scroll` the tabs panel | `squeeze` the tabs. */
	oneRowOverflow?: string,
	pinnedSeparateRow?: boolean,
	showFileIcon?: boolean,
	showExtension?: boolean,
	showDirectoryForNonUnique?: boolean,
	/**  Mark modified tabs with an asterisk. */
	markModified?: boolean,
	showFullPathOnHover?: boolean,
	showCloseButton?: boolean,
	/**  `right` | `left` (with `show_close_button`). */
	closeButtonPosition?: string,
	sortAlphabetically?: boolean,
	previewTab?: boolean,
	openAtEnd?: boolean,
	tabLimit?: number,
	/**  When the limit is reached close `unchanged` (non-modified) tabs first, or the `lru` one. */
	closingPolicy?: string,
	/**  When the current tab is closed activate the `left` | `right` | `mru` tab. */
	activateOnClose?: string,
};

/**  Editor › File Encodings. */
export type EncodingSettings = {
	/**  Fallback for files outside the project that are not valid UTF-8 (WHATWG label). */
	global?: string,
	/**  Encoding of new files and fallback for project files that are not valid UTF-8. */
	project?: string,
	/**  Fallback for `.properties` files. */
	properties?: string,
	/**  Create UTF-8 files: `never` (no BOM) | `always` (with BOM) | `windows` (with BOM on Windows). */
	utf8Bom?: string,
};

export type EntryKind = "file" | "dir" | "symlink";

export type ErrorKind = "notFound" | "alreadyExists" | "permissionDenied" | "invalidInput" | 
/**  Document version mismatch; the UI must resync the full text. */
"outOfSync" | "cancelled" | 
/**  A required external tool (language server, git, debugger) is unavailable. */
"unavailable" | "io" | "protocol" | "internal";

/**  An exception breakpoint filter offered by an adapter (`exceptionBreakpointFilters`). */
export type ExceptionFilter = {
	filter: string,
	label: string,
	description: string | null,
	/**  Enabled unless the user chose otherwise. */
	default: boolean,
	supportsCondition: boolean,
};

/**  Result of `expression_at` (Extract Variable / Introduce … fallback). */
export type ExpressionAt = {
	/**
	 *  The expression exactly matching the (whitespace-trimmed) selection, else
	 *  the smallest expression enclosing it; for an empty selection the
	 *  innermost expression at the caret. `None` when the selection is not
	 *  inside an expression.
	 */
	expression: SyntaxNode | null,
	/**  `expression` spans exactly the trimmed selection. */
	exact: boolean,
	/**
	 *  Expressions from `expression` outwards up to the statement, innermost
	 *  first (IDEA's "choose expression" popup for a caret selection).
	 */
	candidates: SyntaxNode[],
	/**  The statement (direct child of a block / statement list) containing the expression. */
	statement: SyntaxNode | null,
	/**  The block / statement list that contains `statement`. */
	block: SyntaxNode | null,
	/**
	 *  Innermost lambda / nested function between the expression and the
	 *  statement: inserting a declaration before `statement` would move the
	 *  expression out of that function, so callers must not do it blindly.
	 */
	functionBoundary: SyntaxNode | null,
	/**  The statement (or the expression when there is none) contains syntax errors. */
	hasError: boolean,
};

/**  Tools › External Tools entry. */
export type ExternalTool = {
	id?: string,
	name?: string,
	description?: string,
	group?: string,
	enabled?: boolean,
	program?: string,
	/**  Arguments with macros (`$FilePath$`, `$ProjectFileDir$`…), shell-quoted. */
	arguments?: string,
	workingDirectory?: string,
	synchronizeAfter?: boolean,
	openConsole?: boolean,
};

export type FileCoverage = {
	path: IpcPath,
	/**  Sorted by line. */
	lines: LineCoverage[],
	linesTotal: number,
	linesCovered: number,
	branchesTotal: number,
	branchesCovered: number,
};

export type FileEdit = { kind: "edit"; path: IpcPath; edits: TextEdit[] } | { kind: "create"; path: IpcPath; overwrite: boolean } | { kind: "rename"; from: IpcPath; to: IpcPath } | { kind: "delete"; path: IpcPath; recursive: boolean };

export type FileEntry = {
	name: string,
	path: IpcPath,
	kind: EntryKind,
	size: number,
	/**  Milliseconds since the Unix epoch. */
	mtimeMs: number | null,
	/**  Matched by .gitignore or the exclude settings. */
	ignored: boolean,
	/**  Matched by the exclude settings (IDEA's "excluded": dimmed, excluded-folder icon). */
	excluded: boolean,
	hidden: boolean,
	/**
	 *  For symlinks: what the link points to (`None` when dangling); `None`
	 *  for other entries.
	 */
	targetKind?: EntryKind | null,
};

/**  Identifier occurrences in one file (`identifiers_in_files`). */
export type FileIdentifiers = {
	path: IpcPath,
	occurrences: IdentifierOccurrence[],
};

export type FileMatch = {
	path: IpcPath,
	/**  Path relative to the project root, as displayed. */
	relPath: string,
	score: number,
	/**  Matched char indices within `rel_path`. */
	indices: number[],
};

/**  All matches in one file; streamed to the UI as they are found. */
export type FileMatches = {
	path: IpcPath,
	relPath: string,
	matches: LineMatch[],
};

/**  One file or folder move. */
export type FileMove = {
	from: IpcPath,
	to: IpcPath,
};

/**  What the editor needs to know before choosing a viewer for a file. */
export type FileProbe = {
	size: number,
	/**  Content looks binary (same heuristic as text loading). */
	binary: boolean,
	/**  Above the read-only threshold: the text editor would open it read-only. */
	tooLarge: boolean,
};

/**  A path written in a document: an HTML URL attribute, a CSS `url()` / `@import`. */
export type FileReference = {
	range: Range,
	value: string,
};

/**  Reference updates for a file / folder move (`workspace/willRenameFiles`). */
export type FileRenameEdits = {
	/**  Edits of every server that took part, in terms of the paths before the move. */
	edit: WorkspaceEdit,
	/**  Servers asked (their filters matched one of the moved paths). */
	servers: string[],
	/**  Servers that failed; their references are not updated. */
	errors: string[],
};

export type FileSettings = {
	/**  Save on focus loss / tab switch, like IDEA. */
	autoSave?: boolean,
	exclude?: string[],
	/**  Ignored Files and Folders: name patterns hidden everywhere; see [`crate::ignored`]. */
	ignoredNames?: string[],
	trimTrailingWhitespace?: boolean,
	ensureFinalNewline?: boolean,
	/**  Local History keeps changes from this many working days (days with changes), like IDEA. */
	localHistoryDays?: number,
	/**  Upper bound for a project's Local History in MB; the oldest revisions go first. */
	localHistoryMaxMb?: number,
	/**  File Types › Recognized File Types: the user's changes, by language id. */
	fileTypes?: { [key in string]: FileTypeAssociation },
	/**  Override File Type: file (project-relative and `/`-separated, or absolute) → language id. */
	fileTypeOverrides?: { [key in string]: string },
};

export type FileStamp = {
	size: number,
	mtime: number | null,
};

export type FileStatus = {
	path: IpcPath,
	relPath: string,
	/**  Staged change, if any. */
	staged: ChangeKind | null,
	/**  Unstaged (working tree) change, if any. */
	unstaged: ChangeKind | null,
	renamedFrom: string | null,
};

/**  One language's file name and hashbang patterns on top of its definition. */
export type FileTypeAssociation = {
	/**  Added file name patterns: `*.foo`, `Jenkinsfile`, `Dockerfile.*` (`*` and `?` wildcards). */
	patterns?: string[],
	/**  Patterns of the definition (`*.ext`, file names) the user removed. */
	removedPatterns?: string[],
	/**  Interpreters run by a `#!` first line, e.g. `node` for `#!/usr/bin/env node`. */
	hashbangs?: string[],
};

export type FoldKind = "region" | "comment" | "imports";

export type FoldRange = {
	start_line: number,
	end_line: number,
	kind: FoldKind,
};

/**  Editor › General › Code Folding. */
export type FoldingSettings = {
	showOutline?: boolean,
	fileHeader?: boolean,
	imports?: boolean,
	docComments?: boolean,
};

export type FormatOptions = {
	tabSize: number,
	insertSpaces: boolean,
};

/**  One occurrence of a duplicated code fragment. */
export type Fragment = {
	path: IpcPath,
	relPath: string,
	range: Range,
	/**  The fragment's source, from the start of its first line (capped). */
	text: string,
};

/**
 *  A method breakpoint (DAP function breakpoint). `name` uses the adapter's syntax:
 *  `pkg.Class#method` for java-debug, `pkg.Func` / `pkg.(*T).Method` for Delve, a plain
 *  function name for debugpy and LLDB.
 */
export type FunctionBreakpoint = {
	name: string,
	condition: string | null,
	hitCondition: string | null,
	enabled: boolean,
};

export type GeneralSettings = {
	reopenLastProject?: boolean,
	confirmExit?: boolean,
	/**  Where Open… puts a project while one is open: `ask` | `new` | `same`. */
	openProjectIn?: string,
	/**  Initial folder of the Open / Clone dialogs; empty = the OS default. */
	defaultProjectDirectory?: string,
	/**  Save all files after `idle_seconds` without input. */
	saveOnIdle?: boolean,
	idleSeconds?: number,
	dateFormat?: DateFormatSettings,
	/**
	 *  File › Power Save Mode: no automatic popups (completion, parameter info,
	 *  quick documentation) or background highlighting (usages, code vision).
	 */
	powerSaveMode?: boolean,
	/**  File › Rename Project… (project layer): the name shown for the project; empty = its folder name. */
	projectName?: string,
};

/**  Whether pull requests can be shown for the project, and why not. */
export type GhAvailability = { kind: "ready"; repo: GhRepo; 
/**  The signed-in user. */
login: string | null } | 
/**  No `gh` executable was found. */
{ kind: "notInstalled" } | 
/**  `gh auth login` has not been run (or the token expired). */
{ kind: "notLoggedIn"; message: string } | 
/**  The project has no GitHub remote (or is not a git repository). */
{ kind: "notGitHub"; message: string } | { kind: "error"; message: string };

export type GhRepo = {
	/**  `owner/name`. */
	nameWithOwner: string,
	url: string,
	defaultBranch: string | null,
};

export type GitExecutableInfo = {
	/**  `git version …` output. */
	version: string,
	/**  The executable that was run. */
	path: string,
};

export type GitOperation = 
/**  Continue the merge / rebase / cherry-pick / revert in progress. */
{ op: "continue" } | { op: "abort" } | { op: "skip" } | 
/**  Commits oldest first. */
{ op: "cherryPick"; commits: string[] } | 
/**  Commits newest first. */
{ op: "revert"; commits: string[] } | { op: "reset"; commit: string; mode: ResetMode } | 
/**  Rebases `base..HEAD` (`base: None` = from the root) following `entries`, oldest first. */
{ op: "interactiveRebase"; base: string | null; entries: RebaseEntry[] };

export type GitSettings = {
	/**  Path to the git executable; empty = auto-detect. */
	executable?: string,
	/**  Default of Update Project: `merge` | `rebase`. */
	updateMethod?: string,
	/**  Push rejected (non-fast-forward): update the branch and push again. */
	autoUpdateOnPushRejected?: boolean,
	warnCrlf?: boolean,
	warnDetachedHead?: boolean,
	/**  Background check for incoming commits: `auto` | `always` | `never`. */
	incomingCheck?: string,
	/**  Branch name globs, `;`/`,`-separated; force push to them is prohibited. */
	protectedBranches?: string,
	/**  Initial state of Commit Options › Sign-off Commit. */
	signOff?: boolean,
};

export type GoSettings = {
	/**  Empty = the `go` on `PATH`. */
	goroot?: string,
	/**  Empty = `go env GOPATH`. */
	gopath?: string,
};

export type GotoKind = "definition" | "declaration" | "typeDefinition" | "implementation";

export type GradleModel = {
	/**  Project-relative directory of the build (where `settings.gradle` is); `""` = project root. */
	dir: string,
	/**  The root project first, then subprojects in `include` order. */
	projects: GradleProject[],
	javaVersion: number | null,
	/**  `gradlew` of the build (absolute), else `gradle`. */
	command: string,
	/**  Environment for runs (`JAVA_HOME`); filled in by the shell. */
	env: { [key in string]: string },
	/**  When the task list was last read from Gradle (Unix ms); `None` = static defaults. */
	syncedAt: number | null,
	stale: boolean,
	syncError: string | null,
};

export type GradleProject = {
	/**  Gradle path: `:` for the root project, `:app`, `:libs:core`. */
	path: string,
	name: string,
	/**  Project-relative directory. */
	dir: string,
	/**  Project-relative build script, if any. */
	buildFile: string | null,
	tasks: GradleTask[],
};

export type GradleTask = {
	name: string,
	/**  Lower-case group (`build`, `build setup`, `other`). */
	group: string,
	description: string | null,
};

export type HierarchyDirection = 
/**  Callers / supertypes. */
"incoming" | 
/**  Callees / subtypes. */
"outgoing";

export type HierarchyItem = {
	name: string,
	kind: SymbolKind,
	detail: string | null,
	/**  File path, or the URI of a virtual document (see `uri`). */
	path: IpcPath,
	/**  Set for non-`file:` items (library classes). */
	uri?: string | null,
	range: Range,
	selectionRange: Range,
	/**  Call sites, for call hierarchy. */
	fromRanges: Range[],
};

export type Highlight = {
	range: Range,
	kind: HighlightKind,
};

export type HighlightKind = "text" | "read" | "write";

export type HistoryEntry = {
	/**  Content hash (blake3 hex); identifies the stored blob. Empty for labels. */
	id: string,
	path: IpcPath,
	timestampMs: number | null,
	/**  e.g. "Saved", "External change", "Deleted", "Before refactoring: Move". */
	label: string,
	size: number,
	kind?: HistoryKind,
};

export type HistoryKind = 
/**  A stored revision of `path`. */
"snapshot" | 
/**
 *  A user label ("Put Label…") or system event ("Before Git checkout")
 *  for everything under `path` (the project root); has no content.
 */
"label";

/**  Result of [`DebugManager::redefine_classes`]. */
export type HotSwapResult = {
	/**  Fully qualified names of the classes reloaded (empty: nothing had changed). */
	changedClasses: string[],
	errorMessage: string | null,
};

export type Hover = {
	contents: Markup,
	range: Range | null,
};

/**  One request with its outcome. */
export type HttpExchange = {
	entry: HttpHistoryEntry,
	request: PreparedRequest,
	response: HttpResponse | null,
};

export type HttpHistoryEntry = {
	id: string,
	/**  Unix epoch, ms. */
	timeMs: number | null,
	name: string | null,
	method: string,
	url: string,
	/**  `None` when the request failed. */
	status: number | null,
	totalMs: number | null,
	/**  The `.http` file the request came from. */
	file: IpcPath | null,
	error: string | null,
};

/**  One request of a file, as shown by the gutter and the Run All list. */
export type HttpRequestBlock = {
	/**  0-based index among the file's requests. */
	index: number,
	name: string | null,
	method: string,
	/**  URL as written (variables not substituted). */
	url: string,
	/**  0-based line of the request line. */
	line: number,
	/**  First and last line (0-based, inclusive) of the block, separator excluded. */
	startLine: number,
	endLine: number,
};

export type HttpResponse = {
	status: number,
	statusText: string,
	version: string,
	headers: ([string, string])[],
	contentType: string | null,
	/**  Body as text (lossy UTF-8); `None` for binary bodies. */
	body: string | null,
	/**  Size in bytes as received (after decompression). */
	size: number | null,
	truncated: boolean,
	/**  Request start → response headers. */
	ttfbMs: number | null,
	/**  Request start → body fully read. */
	totalMs: number | null,
};

export type HunkKind = "added" | "modified" | "deleted";

/**  A hunk identified by its line ranges (0-based), see [`LineHunk`]. */
export type HunkRange = {
	start: number,
	lines: number,
	oldStart: number,
	oldLines: number,
};

/**
 *  The single error type that crosses the IPC boundary.
 * 
 *  Crates keep rich internal errors and convert at their public edge; the UI
 *  switches on `kind` and shows `message`.
 */
export type IdeError = {
	kind: ErrorKind,
	message: string,
};

export type IdeEvent = 
/**  Files or directories changed on disk (after debouncing, ignore rules applied). */
{ type: "fsChanged"; created: IpcPath[]; modified: IpcPath[]; removed: IpcPath[] } | 
/**
 *  The backend changed a document (reload from disk, formatting, refactoring).
 *  The UI applies `changes` on top of `base_version`, yielding `version`.
 */
{ type: "docPatched"; doc: DocId; baseVersion: number; version: number; changes: TextChange[] } | 
/**  A document's dirty flag changed (saved / modified externally). */
{ type: "docDirty"; doc: DocId; dirty: boolean } | 
/**  An open document's language changed (Settings › File Types, Override File Type). */
{ type: "docLanguage"; doc: DocId; language: LanguageId } | 
/**  Full replacement of diagnostics for one file from one producer. */
{ type: "diagnostics"; path: IpcPath; source: string; items: Diagnostic[] } | 
/**  Progress of a background task; `fraction` is `None` when indeterminate. */
{ type: "task"; id: TaskId; title: string; message: string | null; fraction: number | null; done: boolean } | 
/**  Project indexing state changed (dumb mode on/off). */
{ type: "indexState"; indexing: boolean; files: number; symbols: number } | 
/**  Git status / branch information should be refreshed. */
{ type: "vcsChanged"; root: IpcPath } | { type: "languageServer"; server: ServerId; name: string; status: ServerStatus; message: string | null } | 
/**
 *  A stopped language server left the project's list (disabled in settings, or a
 *  fallback that a preferred server took over from again).
 */
{ type: "languageServerRemoved"; server: ServerId } | 
/**
 *  A language server asked clients to re-request one kind of data for its
 *  open documents (`workspace/inlayHint/refresh`, …), e.g. after indexing.
 */
{ type: "lspRefresh"; server: ServerId; kind: LspRefreshKind } | { type: "terminalExited"; terminal: TerminalId; code: number | null } | { type: "runExited"; run: RunId; code: number | null } | { type: "debug"; session: DebugSessionId; event: DebugEvent } | { type: "notify"; level: NotifyLevel; title: string; body: string | null } | 
/**
 *  A setting was written (any window); the windows it concerns (all for a
 *  global value, the project's for a project value) re-read their effective settings.
 */
{ type: "settingsChanged"; key: string } | 
/**
 *  The project's source / test / resource / excluded roots changed (build files
 *  changed or folders were marked); the UI re-reads them with `project_roots`.
 */
{ type: "projectRootsChanged"; root: IpcPath } | 
/**  A child process (`ssh`, `git`) asks for a credential; answered with `ssh_askpass_answer`. */
{ type: "askpass"; id: number; prompt: string; kind: AskpassKind } | 
/**  Prompt `id` was answered (in any window) or gave up. */
{ type: "askpassDone"; id: number };

/**  An identifier-like token whose text equals the searched name. */
export type IdentifierOccurrence = {
	range: Range,
	/**  Node kind, e.g. `identifier`, `type_identifier`, `property_identifier`. */
	kind: string,
	/**
	 *  Member / label position (`obj.name`, `name: value` labels): refers to
	 *  a member, not to a variable in scope.
	 */
	qualified: boolean,
};

export type IndentConfig = IndentConfig_Serialize | IndentConfig_Deserialize;

export type IndentConfig_Deserialize = {
	"tab-size": number,
	"insert-spaces": boolean,
};

export type IndentConfig_Serialize = {
	tabSize: number,
	insertSpaces: boolean,
};

export type IndentStyle = "space" | "tab";

export type IndexStatus = {
	indexing: boolean,
	files: number,
	symbols: number,
};

export type InlayHint = {
	position: Pos,
	label: string,
	kind: InlayKind,
	paddingLeft: boolean,
	paddingRight: boolean,
	tooltip: string | null,
	/**
	 *  The label's parts when the server split it (empty for a plain label);
	 *  their values concatenate to `label`.
	 */
	parts: InlayLabelPart[],
};

/**  Editor › Inlay Hints. */
export type InlayHintsSettings = {
	types?: boolean,
	parameters?: boolean,
	/**  Hints of other kinds (chaining, closing labels…). */
	other?: boolean,
	disabledLanguages?: string[],
	/**  Code vision: usages above declarations. */
	codeVisionUsages?: boolean,
	/**  Code vision: last author of a declaration (VCS blame) beside its usages. */
	codeVisionAuthor?: boolean,
};

export type InlayKind = "type" | "parameter" | "other";

/**  One part of an inlay hint label, e.g. a type name that navigates to its declaration. */
export type InlayLabelPart = {
	value: string,
	tooltip: string | null,
	/**  Declaration the part stands for (⌘-click navigates there). */
	location: Location | null,
};

/**  One `textDocument/inlineCompletion` suggestion (ghost text at the caret). */
export type InlineCompletionItem = {
	/**  Text that replaces `range`; snippets arrive as their plain text. */
	insertText: string,
	/**  Replaced range; `None` inserts at the caret. */
	range: Range | null,
	/**  What the typed text is matched against while the suggestion stays shown (default: `insert_text`). */
	filterText: string | null,
	/**  Run after the suggestion is accepted. */
	command: Command | null,
	server: ServerId,
};

/**
 *  Editor › General › Inline Completion: ghost text from language servers that
 *  support `textDocument/inlineCompletion` (LSP 3.18).
 */
export type InlineCompletionSettings = {
	enabled?: boolean,
	/**  Ask only once typing has paused for `pause_ms`, instead of right after each change. */
	onlyOnPause?: boolean,
	pauseMs?: number,
	disabledLanguages?: string[],
};

export type InspectEvent = 
/**  Files about to be inspected. */
{ type: "started"; total: number } | 
/**  A file finished (with or without problems). */
{ type: "file"; file: InspectedFile; done: number } | { type: "done"; summary: InspectSummary };

export type InspectSummary = {
	/**  Files inspected by a language server. */
	files: number,
	problems: number,
	/**  Files in scope no language server serves. */
	skipped: number,
	/**  Files whose server failed or never became ready. */
	failed: number,
	cancelled: boolean,
	elapsedMs: number,
};

export type InspectedFile = {
	path: IpcPath,
	relPath: string,
	diagnostics: Diagnostic[],
};

/**  IDEA's highlighting levels. */
export type InspectionLevel = "error" | "warning" | "weakWarning" | "serverProblem" | "typo" | 
/**  Reported (Problems, Inspect Code) but not highlighted in the editor. */
"none";

/**  Changes to one inspection; absent fields keep the inspection's defaults. */
export type InspectionOverride = {
	enabled?: boolean | null,
	severity?: InspectionLevel | null,
	/**
	 *  The inspection's own options (Typo: `processCode`, `processLiterals`,
	 *  `processComments`); absent ones keep their defaults.
	 */
	options?: { [key in string]: boolean } | null,
};

export type InspectionSettings = {
	/**
	 *  Profile in effect for the project: `default`, `project`, or a copy
	 *  as `ide:<key>` / `project:<key>`.
	 */
	profile?: string,
	/**  The `Default` profile (IDE level): inspection id → override. */
	default?: { [key in string]: InspectionOverride },
	/**  The `Project Default` profile (stored with the project). */
	project?: { [key in string]: InspectionOverride },
	/**  Profiles copied at IDE level (global settings), by key. */
	ideProfiles?: { [key in string]: CustomInspectionProfile },
	/**  Profiles copied at project level (project settings), by key. */
	projectProfiles?: { [key in string]: CustomInspectionProfile },
};

/**  A command line that installs a missing tool (run in the Run tool window). */
export type InstallCommand = {
	command: string,
	args: string[],
	cwd: IpcPath | null,
};

/**  Streamed install progress. */
export type InstallEvent = 
/**  One line of installer output. */
{ type: "line"; text: string } | 
/**  Download progress; `fraction` is 0..1 when the size is known. */
{ type: "progress"; fraction: number | null; message: string };

/**  Optional parts of the invalidation; the symbol index is always rebuilt. */
export type InvalidateCachesOptions = {
	/**  Local History of every project. */
	localHistory?: boolean,
	/**  Language server workspaces (jdtls `-data`, …): servers re-import the project. */
	languageServers?: boolean,
	/**  Build tool sync results (Maven / Gradle) and other per-project caches. */
	buildCaches?: boolean,
};

/**  A path field of an IPC type. */
export type IpcPath = string;

export type Isolation = 
/**  A new git worktree on its own branch. */
"worktree" | 
/**  The project's own checkout. */
"local";

export type IssueLink = {
	/**  Regular expression matched in commit messages. */
	pattern?: string,
	/**  Link with `$0` (whole match) / `$1`… (groups) placeholders. */
	link?: string,
};

/**  Result of `java/buildWorkspace` (jdtls `BuildWorkspaceStatus`). */
export type JavaBuildStatus = "failed" | "succeeded" | 
/**  Compiled, but some project has compile errors. */
"withErrors" | "cancelled";

/**  One error diagnostic; `line` / `column` are 1-based for display. */
export type JavaCompileError = {
	path: IpcPath,
	line: number,
	column: number,
	message: string,
};

/**  Everything needed to launch a class of a module: build outcome, classpath and JDK. */
export type JavaLaunchInfo = {
	/**  `None` when no build was requested. */
	build: JavaBuildStatus | null,
	projectRoot: IpcPath | null,
	classPaths: string[],
	modulePaths: string[],
	/**  JDK home jdtls compiles the project against. */
	javaHome: IpcPath | null,
	/**  The `java` launcher to use (filled in by the caller from the installed JDKs). */
	javaExec: string | null,
	/**
	 *  How a launcher that builds the command line itself must shorten it (java-debug's
	 *  `shortenCommandLine`: `none` | `jarmanifest` | `argfile`; filled in by the caller).
	 */
	shortenCommandLine: string | null,
	/**  First compile errors of the workspace when the build had errors. */
	errors: JavaCompileError[],
	/**  All compile errors (`errors` is capped). */
	errorCount: number,
	/**  Likely causes of the errors worth telling the user (e.g. a missing Lombok agent). */
	hints: string[],
};

export type JavaSettings = {
	/**
	 *  Project JDK home; empty = per module, the installed JDK matching the
	 *  Java version it targets.
	 */
	jdk?: string,
	/**
	 *  JDK home the Java language server (jdtls) runs on, apart from the project
	 *  JDK (IDEA's "JDK for importer"); empty = the project JDK when new enough,
	 *  else the first installed one that is.
	 */
	jdtlsJdk?: string,
	/**
	 *  Extra JVM options for the Java language server (jdtls), space-separated
	 *  (VS Code's `java.jdt.ls.vmargs`).
	 */
	jdtlsVmArgs?: string,
	/**  Build Tools › Maven. */
	maven?: MavenSettings,
};

/**  Java versions a vendor publishes. */
export type JdkReleases = {
	/**  Feature versions, newest first. */
	versions: number[],
	/**  The long-term-support ones among them. */
	lts: number[],
	/**  The version offered first (the newest LTS). */
	recommended: number,
};

/**  A JDK distribution the IDE can download. */
export type JdkVendor = {
	id: string,
	name: string,
};

/**  Editor › Code Style › <Language> › Tabs and Indents (unset fields inherit). */
